sections.text:
נתונה המחלקה Airport שיש לה תכונה אחת: מערך חד־ממדי flights מטיפוס Flight.
הנח שלכל תכונה במחלקה Flight הוגדרו פעולות get ו-set.
במחלקה Airport נתונה פעולה פנימית בוליאנית isFly, שמטרתה לבדוק אם במערך הטיסות flights יש טיסה של חברת התעופה "Sky". הפעולה מחזירה true אם במערך flights יש טיסה של חברת התעופה "Sky", אחרת הפעולה מחזירה false.
הנח שכל התאים במערך שונים מ-null.
הפעולה הנתונה שלפניך שגויה:
public boolean isFly()
{
    for (int i = 0; i < this.flights.length; i++)
    {
        if (this.flights[i].getName().equals("Sky"))
            return true;
        return false;
    }
}
(1) כתוב מה תחזיר הפעולה השגויה עבור מערך flights בגודל 4, שערכי תכונת name של העצמים במערך הם:
במקום הראשון: "Cloud"
במקום השני: "Air"
במקום השלישי: "Sky"
במקום הרביעי: "Travel"
(2) הסבר מהי השגיאה בפעולה.
(3) תקן את הפעולה כדי שהיא תבצע את הנדרש.
במעטפת הפעולה השגויה נמצאת במחלקה Airport בשם isFlyWrong (אפשר להריץ אותה ולבדוק את התשובה ל-(1)), ואת הפעולה המתוקנת כותבים בשם isFly.

classes.code:
public class Time {
    private int hour;
    private int minute;

    public int getHour() { return hour; }
    public void setHour(int hour) { this.hour = hour; }
    public int getMinute() { return minute; }
    public void setMinute(int minute) { this.minute = minute; }
}

public class Flight {
    private String name;
    private String destination;
    private String flightCode;
    private Time flightTime;

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getDestination() { return destination; }
    public void setDestination(String destination) { this.destination = destination; }
    public String getFlightCode() { return flightCode; }
    public void setFlightCode(String flightCode) { this.flightCode = flightCode; }
    public Time getFlightTime() { return flightTime; }
    public void setFlightTime(Time flightTime) { this.flightTime = flightTime; }
}

public class Airport {
    private Flight[] flights;

    public Airport(Flight[] flights) {
        this.flights = flights;
    }

    public Flight[] getFlights() { return flights; }
    public void setFlights(Flight[] flights) { this.flights = flights; }

    // הפעולה השגויה מהשאלה (סעיף ג)
    public boolean isFlyWrong() {
        for (int i = 0; i < this.flights.length; i++) {
            if (this.flights[i].getName().equals("Sky"))
                return true;
            return false;
        }
        return false;
    }
}

tasks.solution:
public Time(int hour, int minute) {
    if (hour >= 0 && hour <= 23) {
        this.hour = hour;
    } else {
        this.hour = 0;
    }
    if (minute >= 0 && minute <= 59) {
        this.minute = minute;
    } else {
        this.minute = 0;
    }
}

public Flight(String name, String destination, String flightCode, Time flightTime) {
    this.name = name;
    this.destination = destination;
    this.flightCode = flightCode;
    this.flightTime = flightTime;
}

public boolean isFly() {
    for (int i = 0; i < this.flights.length; i++) {
        if (this.flights[i].getName().equals("Sky")) {
            return true;
        }
    }
    return false;   // רק אחרי שעברנו על כל המערך
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
Time t1 = new Time(14, 30);
System.out.println("סעיף א, בדיקה 1: " + check(t1.getHour() + " " + t1.getMinute(), "14 30"));
Time t2 = new Time(25, 10);
System.out.println("סעיף א, בדיקה 2: " + check(t2.getHour() + " " + t2.getMinute(), "0 10"));
Time t3 = new Time(8, 60);
System.out.println("סעיף א, בדיקה 3: " + check(t3.getHour() + " " + t3.getMinute(), "8 0"));
Time t4 = new Time(-1, -5);
System.out.println("סעיף א, בדיקה 4: " + check(t4.getHour() + " " + t4.getMinute(), "0 0"));
Flight f1 = new Flight("Sky", "Rome", "SK100", new Time(10, 15));
System.out.println("סעיף ב, בדיקה 1: " + check(f1.getName() + " " + f1.getDestination() + " " + f1.getFlightCode(), "Sky Rome SK100"));
System.out.println("סעיף ב, בדיקה 2: " + check(f1.getFlightTime() == null ? "null" : f1.getFlightTime().getHour() + ":" + f1.getFlightTime().getMinute(), "10:15"));
Flight[] four = { new Flight("Cloud", "Paris", "CL1", new Time(6, 0)), new Flight("Air", "London", "AI2", new Time(9, 30)),
        new Flight("Sky", "Rome", "SK3", new Time(12, 45)), new Flight("Travel", "Athens", "TR4", new Time(18, 5)) };
Airport a1 = new Airport(four);
Airport a2 = new Airport(new Flight[] { new Flight("Cloud", "Paris", "CL1", new Time(6, 0)), new Flight("Air", "London", "AI2", new Time(9, 30)) });
Airport a3 = new Airport(new Flight[] { new Flight("Air", "London", "AI2", new Time(9, 30)), new Flight("Travel", "Athens", "TR4", new Time(18, 5)),
        new Flight("Sky", "Rome", "SK3", new Time(12, 45)) });
System.out.println("סעיף ג (1): הפעולה השגויה מחזירה עבור המערך מהשאלה: " + a1.isFlyWrong());
System.out.println("סעיף ג, בדיקה 1: " + check(a1.isFly(), true));
System.out.println("סעיף ג, בדיקה 2: " + check(a2.isFly(), false));
System.out.println("סעיף ג, בדיקה 3: " + check(a3.isFly(), true));

